contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address recipient, uint256 extraEth) public {
        vm.assume(recipient != address(0) && recipient != address(c));
        vm.assume(extraEth < type(uint256).max / 2);

        // The contract needs enough ETH to pay the bonus (100).
        uint256 bonus = 100;
        // Fund the contract with bonus + extraEth to make balance changes measurable
        vm.deal(address(c), bonus + extraEth);

        uint256 balanceBefore = address(c).balance;

        // Claim the bonus, which internally calls withdrawReward.
        c.getFirstWithdrawalBonus(recipient);

        uint256 balanceAfter = address(c).balance;

        // Reference invariant: after a successful first-time bonus claim,
        // the contract's balance MUST decrease by exactly the bonus amount (100).
        // The buggy version fails to reset rewardsForA, allowing a second claim
        // to succeed and drain more ETH, but the immediate invariant also ensures
        // the internal state is properly cleared for this single claim.
        // The fuzzer can vary extraEth to test with different initial balances.
        assertEq(balanceBefore - balanceAfter, bonus);
    }
}

