pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address recipient, uint96 bonusAmount) public {
        vm.assume(recipient != address(0));
        vm.assume(recipient != address(c));
        vm.assume(bonusAmount > 0);

        // deploy a re-entrant attacker that will call withdrawReward again during the first call
        ReentrantAttacker attacker = new ReentrantAttacker(c, bonusAmount);
        // set up rewardsForA for the attacker by mimicking getFirstWithdrawalBonus logic
        // we cannot call getFirstWithdrawalBonus because it also sets claimedBonus and interferes
        // instead, manually set rewardsForA via the public withdraw path.
        // We need the attacker to have a non-zero rewardsForA and then call withdrawReward.
        // To do this, we first give rewardsForA[attacker] a value by calling a valid sequence.
        // But getFirstWithdrawalBonus calls withdrawReward, which will trigger re-entry.
        // So we directly manipulate state through the public API: call getFirstWithdrawalBonus
        // with the attacker as recipient.

        vm.deal(address(c), bonusAmount * 2); // ensure contract has enough to pay twice
        vm.deal(address(attacker), 0);

        // record pre-state
        uint256 preBalance = address(c).balance;

        // trigger: attacker receives a call from withdrawReward and re-enters
        // use try/catch to observe if revert happened (reference should not revert due to _nonReentrant)
        bool ok;
        try c.getFirstWithdrawalBonus(address(attacker)) {
            ok = true;
        } catch {
            ok = false;
        }

        // After the call(s), we compute invariant:
        // rewardsForA[attacker] is public mapping's auto-generated getter
        uint256 postReward = c.rewardsForA(address(attacker));
        uint256 postBalance = address(c).balance;

        // Invariant: preBalance - postBalance == postReward (the net effect of all withdrawals)
        // Since the attacker re-enters exactly once when balance permits,
        // in the reference, the re-entry is blocked by _nonReentrant and only one withdrawal occurs;
        // in the buggy version, the re-entry succeeds because reset is removed, causing two withdrawals.
        // Therefore assertion: the difference in balance equals the remaining rewards (which should be 0 in ref, >0 in bug).
        assertTrue(preBalance - postBalance == postReward);
    }
}

