    function testFuzz_property(address recipient, uint256 rewardAmount) public {
        vm.assume(recipient != address(0));
        vm.assume(rewardAmount > 0);
        // setup: give some reward to recipient so withdrawReward can succeed
        vm.deal(address(c), rewardAmount);
        // use vm.store to directly set rewardsForA since getFirstWithdrawalBonus would fail on second call
        // but we need to use public surface only. Instead, use getFirstWithdrawalBonus for first setup
        // We need to set rewardsForA without hitting the lock issue initially. 
        // Since claimedBonus is initially false, getFirstWithdrawalBonus will set rewards and call withdrawReward
        // To avoid needing a helper for low-level call success, recipient must be an EOA (call always succeeds)
        // So we just use a regular address that will receive ether.
        vm.prank(recipient);
        // first call to getFirstWithdrawalBonus will trigger withdrawReward, setting and resetting lock.
        // But we need to ensure it doesn't revert. We fund the contract.
        // getFirstWithdrawalBonus adds 100 to rewardsForA[recipient] and calls withdrawReward.
        // We need the contract to have at least 100 wei. We'll deal more.
        vm.deal(address(c), 100 + rewardAmount);
        vm.prank(recipient);
        try c.getFirstWithdrawalBonus(recipient) { } catch { }

        // Now the first withdrawReward completed. Lock should be released if correct.
        // Second call to withdrawReward will test the lock.
        // We must have rewardsForA[recipient] > 0 for withdrawReward to send funds.
        // Since getFirstWithdrawalBonus already set rewardsForA[recipient]=0 after withdraw, we need to add more.
        // But we cannot call getFirstWithdrawalBonus again because claimedBonus is true.
        // Instead, we deal additional Ether and use a different approach: we fuzz rewardAmount and set it.
        // However, we cannot directly set private mapping. Alternative: use a second recipient.
        // Wait - we can just fuzz a second recipient for the second call.
        // The property is about _locked state after any withdrawReward call. So we can use two separate recipients.
        address recipient2 = address(uint160(recipient) + 1);
        vm.assume(recipient2 != address(0) && recipient2 != recipient);
        vm.deal(address(c), rewardAmount);
        // Set rewardsForA[recipient2] by using getFirstWithdrawalBonus if not yet claimed.
        vm.prank(recipient2);
        try c.getFirstWithdrawalBonus(recipient2) { } catch { }
        // After getFirstWithdrawalBonus, withdrawReward was called once. Lock reset? Now call withdrawReward again on recipient2.
        // But rewardsForA[recipient2] is now 0. So withdrawReward would send 0 and still succeed but not test lock properly.
        // We need a scenario where we call withdrawReward directly without resetting rewardsForA to 0.
        // Actually, we can just call withdrawReward with the same recipient after getFirstWithdrawalBonus.
        // But rewardsForA[recipient] is 0 after getFirstWithdrawalBonus. The withdrawReward will still execute with amount 0.
        // The lock behavior matters regardless of amount. The transaction itself will succeed if lock is false, revert if lock is true.
        // So we don't need a positive amount. We can just call withdrawReward(recipient) again and check if it reverts.
        vm.prank(recipient);
        bool success;
        try c.withdrawReward(recipient) { success = true; } catch { success = false; }
        // In reference implementation, _locked is reset, so second call succeeds (even with 0 amount).
        // In buggy implementation, _locked remains true, so second call reverts.
        assertTrue(success);
    }
}

